import { Component, createSignal, For, onMount, Show } from "solid-js";

import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { ViewExperience } from "#core/ui-next/services/view-experience.js";
import { useAspectRatio, useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";
import { PropsRef } from "#core/ui-next/utilities/solid-utilities.js";

import { ScreenFrame } from "#base/ui-next/components/screen-frame.jsx";
import { AdvisorTab } from "#base/ui-next/screens/advisor-council/advisor-screen-advice-tab.jsx";
import { CouncilRoom } from "#base/ui-next/screens/advisor-council/advisor-screen-council-tab.jsx";
import {
	AdvisorCouncilScreenContext,
	createAdvisorCouncilScreenModel,
} from "#base/ui-next/screens/advisor-council/advisor-screen-model.js";

export interface AdvisorCouncilComponentProps {
	/** Ref callback to get access to the host element */
	ref?: PropsRef<HTMLDivElement> | undefined;
}

const AdvisorCouncilComponent: Component<AdvisorCouncilComponentProps> = (_props) => {
	const model = createAdvisorCouncilScreenModel();
	const audio = useAudio();
	const [defaultRoomTabId, setDefaultRoomTabId] = createSignal<string>("COUNCIL");
	const [defaultAdviceTabId, setDefaultAdviceTabId] = createSignal<string | undefined>(undefined);

	let rootRef!: HTMLDivElement;

	onMount(() => {
		// Get components HTML attributes
		const tabId = rootRef.parentElement?.getAttribute("tab-id");
		if (tabId) {
			setDefaultRoomTabId(tabId.replace("advisor-", "").toUpperCase());
		}
		const advicePageId = rootRef.parentElement?.getAttribute("page-id");
		if (advicePageId && advicePageId != "undefined") {
			setDefaultAdviceTabId(advicePageId);
		}

		audio("AdvisorScreen", "popup-open");
	});

	const handleOnClosing = () => {
		audio("AdvisorScreen", "popup-close");
	};

	const isMobile = ViewExperience() == UIViewExperience.Mobile;
	const isSmallScreen = useIsSmallScreen();
	const aspectRatio = useAspectRatio();
	return (
		<AdvisorCouncilScreenContext.Provider value={model}>
			<ScreenFrame
				name="Advisor-Council"
				panelContext="screen-advisor-council"
				audioContext="AdvisorScreen"
				onClosing={handleOnClosing}
				ornatePanelData={model.ornatePanelData}
				title="LOC_UI_RADIAL_MENU_DETAILS_ADVISORS_TITLE"
				ref={rootRef}
				isFullscreen={isMobile}
			>
				<Tab
					class="w-full flex flex-col flex-auto pointer-events-auto relative"
					defaultTab={defaultRoomTabId()}
				>
					<Tab.TabList
						class={`advisor-tab-list self-center text-sm font-base ${isSmallScreen() ? "my-5" : aspectRatio() <= 1.335 ? "mt-20 mb-8" : "my-10"}`}
						nextHotkey="nav-next"
						previousHotkey="nav-previous"
					/>

					<Tab.Output />

					<Tab.Item
						name="COUNCIL"
						title={() => "LOC_ADVISOR_COUNCIL_TAB"}
						body={() => (
							<div class={`flex-1 ${isSmallScreen() ? (isMobile ? "mb-14" : "mb-24") : "mb-16"}`}>
								<CouncilRoom isPopup={false} />
							</div>
						)}
					/>

					<For each={model.advisorsData}>
						{(advice) => {
							return (
								<Show when={advice.pages?.length}>
									<Tab.Item
										name={advice.title}
										title={() => `LOC_VICTORY_${advice.title}_MODERN_NAME`}
										body={() => (
											<AdvisorTab
												type={advice.type}
												title={advice.title}
												pages={advice.pages}
												//Naviate to advice page if coming from respective advisors watchout
												defaultTab={
													advice.title === defaultRoomTabId()
														? defaultAdviceTabId()
														: undefined
												}
											/>
										)}
									/>
								</Show>
							);
						}}
					</For>
				</Tab>
			</ScreenFrame>
		</AdvisorCouncilScreenContext.Provider>
	);
};

export const AdvisorCouncil = ComponentRegistry.register({
	name: "AdvisorCouncil",
	createInstance: AdvisorCouncilComponent,
});

defineLegacyComponent("screen-advisor-council", { classNames: ["fullscreen"] }, () => {
	Input.setActiveContext(InputContext.Shell);
	return <AdvisorCouncilComponent />;
});
